import{_ as t,o as r,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const d=JSON.parse('{"title":"产品发布 - 2026-07-01","description":"","frontmatter":{"date":"2026-07-01T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-07-01-product.md","filePath":"daily/2026-07-01-product.md"}'),e={name:"daily/2026-07-01-product.md"};function s(i,o,p,g,l,h){return r(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="产品发布-2026-07-01" tabindex="-1">产品发布 - 2026-07-01 <a class="header-anchor" href="#产品发布-2026-07-01" aria-label="Permalink to &quot;产品发布 - 2026-07-01&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日产品发布领域主要动态包括Notion AI的新功能更新、Notion文档的AI助手扩展以及数字.ai 23.3版本的工作流优化。最值得关注的是Notion AI提升了图像生成限制并整合新模型，以及数字.ai 23.3版本的自助工作流简化了开发者应用上线流程。</p><hr><h3 id="_1-notion-ai更新及新功能" tabindex="-1">1. Notion AI更新及新功能 <a class="header-anchor" href="#_1-notion-ai更新及新功能" aria-label="Permalink to &quot;1. Notion AI更新及新功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://matthiasfrank.de/en/notion-updates" target="_blank" rel="noreferrer">Notion Updates &amp; New Features</a></p><p><strong>一句话摘要</strong>: Notion AI提升图像生成限制并整合新模型</p><p><strong>能解决什么问题</strong>: 提高用户在页面设计时的灵活性和效率</p><p><strong>产品应用</strong>: 适用于需要集中设计工作和跨平台文档管理的场景</p><p><strong>示例场景</strong>: 设计师在Notion中快速迭代页面视觉设计</p><hr><h3 id="_2-notion文档更新日志" tabindex="-1">2. Notion文档更新日志 <a class="header-anchor" href="#_2-notion文档更新日志" aria-label="Permalink to &quot;2. Notion文档更新日志&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://developers.notion.com/page/changelog" target="_blank" rel="noreferrer">Changelog - Notion Docs</a></p><p><strong>一句话摘要</strong>: Notion扩展AI助手功能并发布新的SDK版本</p><p><strong>能解决什么问题</strong>: 提高Notion AI助手的数据库查询能力和API的灵活性</p><p><strong>产品应用</strong>: 适用于企业级用户，通过API增强产品功能</p><p><strong>示例场景</strong>: 企业用户可以直接从AI助手查询数据库</p><hr><h3 id="_3-数字-ai-23-3版本工作流概览" tabindex="-1">3. 数字.ai 23.3版本工作流概览 <a class="header-anchor" href="#_3-数字-ai-23-3版本工作流概览" aria-label="Permalink to &quot;3. 数字.ai 23.3版本工作流概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: 数字.ai 23.3引入自助工作流简化开发者应用上线流程。</p><p><strong>能解决什么问题</strong>: 降低应用部署复杂性，确保云安全和合规性。</p><p><strong>产品应用</strong>: 适用于需要自动化部署和云优化的软件开发项目。</p><p><strong>示例场景</strong>: 开发者使用工作流自动化CI/CD流程。</p><hr><h3 id="_4-今年notion将推出哪些非ai功能" tabindex="-1">4. 今年Notion将推出哪些非AI功能？ <a class="header-anchor" href="#_4-今年notion将推出哪些非ai功能" aria-label="Permalink to &quot;4. 今年Notion将推出哪些非AI功能？&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.reddit.com/r/Notion/comments/1qbod39/what_new_features_will_come_to_notion_this_year" target="_blank" rel="noreferrer">What new features will come to Notion this year that are not AI-based?</a></p><p><strong>一句话摘要</strong>: 讨论Notion今年将推出的非AI新功能。</p><p><strong>能解决什么问题</strong>: 提供更丰富的数据库操作和数据导出功能。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，增强用户体验和工作效率。</p><p><strong>示例场景</strong>: 团队成员可以实时讨论数据库内容。</p><hr><h3 id="_5-产品副驾驶——软件产品团队的ai助手" tabindex="-1">5. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_5-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;5. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: Product Copilot是集成在Jira和Confluence中的AI助手，帮助产品管理。</p><p><strong>能解决什么问题</strong>: 解决产品团队在创建清晰任务、回答问题、清理积压工作和更新文档中的效率问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过集成到Jira和Confluence中，提高团队协作和产品开发速度。</p><p><strong>示例场景</strong>: 产品负责人使用Product Copilot优化他们的积压管理工作。</p><hr><h3 id="_6-微软copilot-组织使用的ai工具" tabindex="-1">6. 微软Copilot | 组织使用的AI工具 <a class="header-anchor" href="#_6-微软copilot-组织使用的ai工具" aria-label="Permalink to &quot;6. 微软Copilot | 组织使用的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软推出基于聊天的生成性AI交互工具。</p><p><strong>能解决什么问题</strong>: 提高工作效率，增强安全性，促进代码编写。</p><p><strong>产品应用</strong>: 可应用于日常办公、安全运维和软件开发。</p><p><strong>示例场景</strong>: 企业使用Microsoft 365 Copilot提高文档处理效率。</p><hr><h3 id="_7-微软副驾驶" tabindex="-1">7. 微软副驾驶 <a class="header-anchor" href="#_7-微软副驾驶" aria-label="Permalink to &quot;7. 微软副驾驶&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Microsoft_Copilot" target="_blank" rel="noreferrer">Microsoft Copilot</a></p><p><strong>一句话摘要</strong>: 微软推出基于大型语言模型的人工智能聊天机器人。</p><p><strong>能解决什么问题</strong>: 替代已停用的Cortana，提供更智能的虚拟助手服务。</p><p><strong>产品应用</strong>: 可用于提升工作效率，如集成到Windows和Microsoft 365中。</p><p><strong>示例场景</strong>: 使用Copilot Studio创建定制化的AI助手。</p><hr><h3 id="_8-ai新闻-导致市场崩溃的ai产品发布" tabindex="-1">8. AI新闻：导致市场崩溃的AI产品发布 <a class="header-anchor" href="#_8-ai新闻-导致市场崩溃的ai产品发布" aria-label="Permalink to &quot;8. AI新闻：导致市场崩溃的AI产品发布&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=xdp8bulnidY&amp;vl=en-US" target="_blank" rel="noreferrer">AI News: The AI Launch That Crashed The Market - YouTube</a></p><p><strong>一句话摘要</strong>: 本周AI领域发生了许多重大新闻，包括OpenAI的新应用和模型发布。</p><p><strong>能解决什么问题</strong>: 提供更高效的编程辅助和多任务处理能力。</p><p><strong>产品应用</strong>: 可以应用于软件开发，提高代码编写效率和多任务管理。</p><p><strong>示例场景</strong>: 开发者使用Codex app编写和优化代码。</p><hr><h3 id="_9-谷歌在英国推出新的人工智能搜索功能" tabindex="-1">9. 谷歌在英国推出新的人工智能搜索功能 <a class="header-anchor" href="#_9-谷歌在英国推出新的人工智能搜索功能" aria-label="Permalink to &quot;9. 谷歌在英国推出新的人工智能搜索功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.bbc.com/news/articles/clyj4zky4zwo" target="_blank" rel="noreferrer">Google launches new &#39;AI mode&#39; search feature in UK</a></p><p><strong>一句话摘要</strong>: 谷歌在英国推出AI搜索模式，提供对话式答案。</p><p><strong>能解决什么问题</strong>: 解决用户对快速、简单答案的需求，提高搜索效率。</p><p><strong>产品应用</strong>: 可应用于搜索引擎，提供更直接的对话式搜索结果。</p><p><strong>示例场景</strong>: 用户询问“如何清洁地毯上的咖啡渍”时，直接得到答案。</p><hr><h3 id="_10-搜索引擎的历史-从目录到人工智能搜索" tabindex="-1">10. 搜索引擎的历史：从目录到人工智能搜索 <a class="header-anchor" href="#_10-搜索引擎的历史-从目录到人工智能搜索" aria-label="Permalink to &quot;10. 搜索引擎的历史：从目录到人工智能搜索&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://audits.com/seo/insights/history-of-search-engines" target="_blank" rel="noreferrer">The History of Search Engines: From Directories to AI Search - Audits.com</a></p><p><strong>一句话摘要</strong>: 搜索引擎从目录发展到AI搜索，提升了信息整合和语义理解能力。</p><p><strong>能解决什么问题</strong>: 解决用户在海量信息中快速准确找到所需内容的问题。</p><p><strong>产品应用</strong>: 可以应用到搜索引擎产品中，通过AI技术提升搜索效率和用户体验。</p><p><strong>示例场景</strong>: 用户搜索“日本旅游”，系统提供个性化推荐和相关问题。</p><hr>',75)])])}const _=t(e,[["render",s]]);export{d as __pageData,_ as default};
